/* 组件就绪后执行 */
Eam.registerInit(async function(){
/* 设备档案控制器：仅绑定现有HTML节点，全部业务读取通过模拟接口。 */
await (async()=>{
  if(document.body.dataset.page!=='device'||!document.getElementById('archive-refresh'))return;
  const id=new URLSearchParams(location.search).get('equipment')||'EQ-001';
  const api=(domain,method='GET',body={})=>EamArchiveApi.request(method,'/equipment/'+encodeURIComponent(id)+'/'+domain,body);
  const el=x=>document.getElementById(x),text=(x,v)=>Eam.text(x,v);
  const labels={overview:'设备概况',parameters:'技术参数',state:'状态与许可',structure:'设备结构',installation:'位置与安装',work:'点检档案',maintenance:'保养档案',failure:'缺陷与故障',repair:'维修档案',bom:'设备BOM',replacement:'更换与寿命',meters:'测点与计量器',trend:'运行监测',risk:'安全合规',restrictions:'使用限制',cost:'资产成本',media:'图片与3D',documents:'文档资料',history:'生命周期',audit:'变更审计',related:'关联业务',completeness:'档案完整性'};
  let summary,active='overview',requestTicket=0,selectedRecord,selectedDomain;
  const listState={};
  const domainUi=EamArchiveDomainUi;
  function facts(node,entries){node.replaceChildren();for(const [label,value] of entries){const wrap=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value===null||value===undefined||value===''?'—':String(value);wrap.append(dt,dd);node.append(wrap);}}
  function tag(value,tone){const t=document.createElement('span');t.className='archive-tag '+tone;t.textContent=value;return t;}
  function openRecord(row,domain){selectedRecord=row;selectedDomain=domain;text('archive-record-title',row.name);facts(el('archive-record-fields'),[['记录编号',row.id],['设备',summary.equipment.code],['业务内容',row.content],['关联依据',row.evidence],['数据来源',row.source],['更新时间',row.updatedAt],['记录版本','V'+row.revision]]);let professional=el('archive-record-professional');if(!professional){professional=document.createElement('div');professional.id='archive-record-professional';el('archive-record-fields').after(professional);}domainUi.details(professional,row,domain);el('archive-record-source').hidden=!row.target;el('archive-record-edit').hidden=domain!=='parameters'||!summary.canEdit;el('archive-release-open').hidden=domain!=='restrictions'||row.status!=='active'||!summary.canRelease||row.canRelease===false;el('archive-record-dialog').showModal();}
  function renderRows(node,rows,domain,display={}){
    const state=listState[domain] ||= {query:'',page:1,status:'',source:'',view:domainUi.views[domain]?.[0][0]||''};
    node.replaceChildren();
    domainUi.controls(node,domain,state.view,rows,view=>{state.view=view;state.page=1;state.status='';state.source='';renderRows(node,rows,domain,display);});
    if(display.source||display.asOf){const scoped=rows.filter(row=>domainUi.matches(domain,state.view,row)),sources=[...new Set(scoped.map(row=>row.source).filter(Boolean))],times=scoped.map(row=>row.updatedAt).filter(value=>Number.isFinite(Date.parse(value))).sort((a,b)=>Date.parse(b)-Date.parse(a));const meta=document.createElement('p');meta.className='archive-panel-source muted';meta.textContent='数据来源：'+(sources.join('、')||display.source||'—')+' · 来源最新业务时间：'+(times[0]||display.asOf||'未记录')+(display.readAt?' · 接口读取：'+display.readAt:'');node.append(meta);}
    if(display.lifetime){const life=display.lifetime,used=life.current-life.baseline,remaining=Math.max(0,life.target-used),metrics=document.createElement('div');metrics.className='archive-kpis';for(const [label,value]of [['在装实例',life.instance],['累计使用',used+' '+life.unit],['剩余寿命',remaining+' '+life.unit]]){const box=document.createElement('div'),caption=document.createElement('span'),number=document.createElement('strong');caption.textContent=label;number.textContent=value;box.append(caption,number);metrics.append(box);}node.append(metrics);const p=document.createElement('p');p.className='muted';p.textContent='目标 '+life.target+' '+life.unit+' · 安装基准 '+life.baseline+' '+life.unit+' · 数据时间 '+life.asOf;node.append(p);}
    const toolbar=document.createElement('div');toolbar.className='list-panel-header';toolbar.dataset.component='list-toolbar';const heading=document.createElement('h2');heading.className='business-panel-title';heading.textContent=labels[domain]+'清单';toolbar.append(heading);
    const search=document.createElement('input');search.type='search';search.value=state.query;search.placeholder='搜索名称、编号或关联记录';search.setAttribute('aria-label',labels[domain]+'搜索');
    const count=document.createElement('span');count.className='muted';const tools=document.createElement('div');tools.className='list-panel-tools';tools.append(EamUiComponents.filterBar(search));const section=node.previousElementSibling;if(section?.classList.contains('sectionhead')&&!section.querySelector('#archive-life-open')){section.hidden=true;for(const button of section.querySelectorAll('button')){const action=button.cloneNode(true);action.classList.add('btn','btn-sm','btn-outline-secondary');tools.append(action);}}toolbar.append(tools);node.append(toolbar);
    const filter=document.createElement('div');filter.className='filter-options';filter.hidden=true;for(const [key,title]of [['status','业务状态'],['source','数据来源']]){const select=document.createElement('select');select.className='form-select';select.setAttribute('aria-label',title);select.append(new Option('全部',''));for(const value of [...new Set(rows.map(row=>row[key]).filter(Boolean))])select.append(new Option(value,value));select.value=state[key]||'';select.onchange=()=>{state[key]=select.value;state.page=1;renderRows(node,rows,domain,display);};filter.append(select);}const reset=document.createElement('button');reset.type='button';reset.textContent='重置筛选';reset.className='btn btn-sm btn-outline-secondary';filter.append(reset);node.append(filter);const advanced=document.createElement('button');advanced.type='button';advanced.className='btn btn-sm btn-outline-secondary';advanced.dataset.component='advanced-filter-trigger';EamUiComponents.toolIcon(advanced,'filter','高级筛选');advanced.onclick=()=>EamUiComponents.openFilter(filter,advanced);tools.querySelector('[data-component="filter-bar"]').append(advanced);const refresh=document.createElement('button');refresh.type='button';refresh.className='btn btn-sm btn-outline-secondary';refresh.textContent='↻';refresh.title='刷新档案';refresh.setAttribute('aria-label','刷新档案');refresh.onclick=async()=>{refresh.disabled=true;try{await load();}finally{refresh.disabled=false;}};tools.append(refresh);
    const results=rows.filter(x=>[x.id,x.name,x.content,x.evidence].join(' ').toLowerCase().includes(state.query.toLowerCase())&&(!state.status||x.status===state.status)&&(!state.source||x.source===state.source)&&domainUi.matches(domain,state.view,x));
    EamArchiveBusinessView.render(domain,results,display,openRecord);
    const pages=Math.max(1,Math.ceil(results.length/8));state.page=Math.min(state.page,pages);count.textContent='共 '+results.length+' 条';
    const region=document.createElement('div');region.className='table-wrapper';
      const table=document.createElement('table');table.className='data-table archive-record-table';
      const thead=document.createElement('thead'),head=document.createElement('tr');
      const columns=domainUi.columns(domain,state.view,display.columns||[['name','记录 / 名称'],['content','业务内容'],['evidence','关联与依据']]);
      for(const [key,title] of [...columns,['action','操作']]){const th=document.createElement('th');th.textContent=title;if(['amount','temperature','hours','downtime'].includes(key))th.className='archive-number';head.append(th);}thead.append(head);table.append(thead);
      const tbody=document.createElement('tbody');
      for(const row of results.slice((state.page-1)*8,state.page*8)){
        const tr=document.createElement('tr');
        for(const [key] of columns){const td=document.createElement('td');let value=row[key]??'—';if(domain==='restrictions'&&key==='status')value=({active:'有效限制',released:'已解除'})[value]||value;if(key==='amount'&&typeof value==='number')value=value.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});if(['amount','temperature','hours','downtime'].includes(key))td.className='archive-number';if(['status','quality'].includes(key))td.append(tag(String(value),['已关闭','已完成','GOOD'].includes(value)?'success':'neutral'));else {const span=document.createElement(key==='name'&&row.target?'button':'span');span.textContent=value;if(span.tagName==='BUTTON'){span.type='button';span.className='btn btn-link p-0 text-start';span.onclick=()=>Eam.go(row.target,row.query);}td.append(span);}if(key==='name'){if(row.source?.includes('历史样本')){const badge=document.createElement('span');badge.className='badge text-bg-secondary ms-2';badge.textContent='历史样本';td.append(badge);}const small=document.createElement('small');small.textContent=row.id;td.append(small);}tr.append(td);}
        const td=document.createElement('td'),button=document.createElement('button');button.type='button';button.textContent='详情';button.setAttribute('aria-label','查看'+row.name+'详情');button.onclick=()=>openRecord(row,domain);td.append(button);if(domain==='completeness'&&(row.canRepair||row.repairTab||row.target)){const repair=document.createElement('button');repair.type='button';repair.textContent=row.canRepair?'补录':row.repairTab?'查看参数':'配置来源';repair.onclick=()=>{if(row.canRepair){selectedRecord=row;el('archive-repair-form').reset();text('archive-repair-label',row.name+' *');const owner=row.field==='ownerId';el('archive-repair-owner').replaceChildren(new Option('请选择负责人',''),...(row.options||[]).map(option=>new Option(option.label,option.value)));el('archive-repair-value').type=row.field==='commissionedAt'?'date':'text';el('archive-repair-value').hidden=owner;el('archive-repair-value').disabled=owner;el('archive-repair-owner').hidden=!owner;el('archive-repair-owner').disabled=!owner;el('archive-repair-owner').required=owner;const required=el('archive-repair-required');required.replaceChildren();for(const item of row.requiredRepairs||[]){const label=document.createElement('label');label.className='field';label.textContent=item.name+'（一并补齐） *';const input=document.createElement(item.options?.length?'select':'input');input.dataset.repairField=item.field;input.required=true;input.className=item.options?.length?'form-select':'form-control';if(item.options?.length)input.append(new Option('请选择',''),...item.options.map(option=>new Option(option.label,option.value)));label.append(input);required.append(label);}text('archive-repair-error','');el('archive-repair-dialog').showModal();}else if(row.repairTab)selectTab(row.repairTab);else Eam.go(row.target,row.query);};td.append(repair);}tr.append(td);tbody.append(tr);
      }table.append(tbody);region.append(table);
    node.append(region);
    const footer=document.createElement('div');EamUiComponents.pagination(footer,{page:state.page,pages,total:results.length,pageSize:8,onChange:page=>{state.page=page;renderRows(node,rows,domain,display);}});node.append(footer);EamUiComponents.decorateTables();
    search.addEventListener('input',()=>{const pos=search.selectionStart;state.query=search.value;state.page=1;renderRows(node,rows,domain,display);const newInput=node.querySelector('input');newInput.focus();try{newInput.setSelectionRange(pos,pos);}catch{}});
  }
  async function loadPanel(){
    const ticket=++requestTicket;el('archive-loading').hidden=false;el('archive-content-head')?.setAttribute('aria-busy','true');
    const node=document.querySelector('[data-record-domain="'+active+'"]');
    if(!node){el('archive-loading').hidden=true;return;}
    renderRows(node,[],active);EamArchiveBusinessView.state(active,'loading');EamUiComponents.setTableStatus(node.querySelector('table'),'loading');
    try{const response=await api('domains/'+active);if(ticket!==requestTicket)return;if(response.code===202)return;renderRows(node,response.data.items,active,response.data);}
    catch(e){if(ticket!==requestTicket)return;if(e.code==='FORBIDDEN'){node.replaceChildren();const box=document.createElement('div');box.className='alert alert-secondary';box.dataset.component='permission-state';box.setAttribute('role','status');box.textContent=e.message;node.append(box);}else{renderRows(node,[],active);EamArchiveBusinessView.state(active,'error',e.message);EamUiComponents.setTableStatus(node.querySelector('table'),'error',e.message,loadPanel);}}
    finally{if(ticket===requestTicket&&Eam.s.scenario!=='loading'){el('archive-loading').hidden=true;el('archive-content-head')?.removeAttribute('aria-busy');}}
  }
  function selectTab(key){const b=document.querySelector('[data-tab="'+CSS.escape(key)+'"]');if(!b)return;active=key;document.body.classList.toggle('archive-media-open',key==='media');text('archive-view-title',labels[key]);for(const tab of document.querySelectorAll('[data-tab]')){tab.classList.toggle('active',tab===b);tab.setAttribute('aria-selected',String(tab===b));tab.tabIndex=tab===b?0:-1;}for(const p of document.querySelectorAll('[data-panel]'))p.hidden=p.dataset.panel!==key;const url=new URL(location.href);url.searchParams.set('tab',key);history.replaceState(null,'',url);loadPanel();}
  async function load(){
    el('archive-page-error').hidden=true;el('archive-refresh').disabled=true;
    try{
      const response=await api('archive');if(response.code===202){el('archive-loading').hidden=false;return;}summary=response.data;
      const e=summary.equipment;document.title=e.name+' · 设备档案';text('device-name',e.name+' · 设备档案');text('device-location',e.code+' / '+(e.location||'位置未维护'));text('device-model',e.model);text('device-owner','负责人 '+e.owner);text('device-serial','序列号 '+(e.serial||'—'));
      const photo=el('archive-photo'),placeholder=el('archive-photo-empty');photo.hidden=!e.image;placeholder.hidden=!!e.image;photo.onerror=()=>{photo.hidden=true;placeholder.hidden=false;};if(e.image)photo.src=e.image;else photo.removeAttribute('src');
      const strip=el('archive-status-strip');strip.replaceChildren();const cards=el('archive-state-cards');cards.replaceChildren();cards.className='row row-cols-1 row-cols-md-2 row-cols-xl-3 g-3';
      for(const state of summary.states){const chip=document.createElement('span');chip.append(document.createTextNode(state.name+' '),tag(state.value,state.tone));strip.append(chip);const card=document.createElement('section');card.className='archive-state-card card h-100 p-3';const h=document.createElement('h3');h.className='h6 mb-2';h.textContent=state.name;const dl=document.createElement('dl');dl.className='small mt-2 mb-0';facts(dl,[['来源',state.source],['业务 / 采集时间',state.time],['适用范围',state.scope||'当前设备']]);for(const item of dl.children){item.className='d-flex gap-2 justify-content-between';item.querySelector('dt').className='fw-normal text-secondary mb-1 flex-shrink-0';item.querySelector('dd').className='mb-1 text-end text-break';}const explanation=document.createElement('p');explanation.className='small text-secondary mt-2 mb-0';explanation.textContent=state.explanation||'由来源流程决定';card.append(h,tag(state.value,state.tone),dl,explanation);const column=document.createElement('div');column.className='col';column.append(card);cards.append(column);}
      text('archive-open-count',summary.pending);text('archive-pm-count',summary.maintenanceCount);text('archive-file-count',summary.fileCount);
      facts(el('archive-base'),['classification','model','manufacturer','serial','assetCode','commissionedAt'].map(k=>[summary.fieldLabels[k],e[k]]));facts(el('archive-organization'),['owner','department','management','team','location','functionalPosition'].map(k=>[summary.fieldLabels[k],e[k]]));
      facts(el('archive-procurement'),[['供应商',e.supplier],['采购合同',e.purchaseContract],['安装验收日期',e.acceptanceDate],['安装验收单',e.acceptanceCode],['质保截止',e.warrantyUntil],['设计寿命',e.designLife]]);
      el('archive-life-open').disabled=!summary.canLifecycle;el('archive-life-open').title=summary.canLifecycle?'当前演示仅开放 EQ-001 生命周期流程':id!=='EQ-001'?'该设备生命周期来源流程尚未开放':'当前角色无生命周期维护权限';
      const restrictions=el('archive-restrictions');restrictions.replaceChildren();
      const rr=await api('domains/restrictions');if(rr.code===200)renderRows(restrictions,rr.data.items,'restrictions');
      for(const cat of ['image','model','document']){const b=el('upload-device-'+cat);b.disabled=!summary.canEdit;b.onclick=()=>EamOpenAssets(cat);}
      await window.EamArchiveGallery?.refresh();
      selectTab(active);
    }catch(e){text('archive-page-error-text',e.message);el('archive-page-error').hidden=false;document.querySelector('.archive-workspace').hidden=true;}
    finally{el('archive-refresh').disabled=false;}
  }
  for(const b of document.querySelectorAll('[data-tab]'))b.addEventListener('click',()=>selectTab(b.dataset.tab));
  for(const b of document.querySelectorAll('[data-tab-target]'))b.onclick=()=>{const domain=b.dataset.tabTarget;if(b.dataset.viewTarget){const state=listState[domain] ||= {query:'',page:1,status:'',source:''};Object.assign(state,{view:b.dataset.viewTarget,page:1,query:'',status:'',source:''});}selectTab(domain);};
  window.addEventListener('eam-archive-files-updated',load);el('archive-refresh').onclick=load;el('archive-retry').onclick=()=>{document.querySelector('.archive-workspace').hidden=false;load();};
  
  el('archive-record-close').onclick=()=>el('archive-record-dialog').close();
  el('archive-release-open').onclick=()=>{el('archive-record-dialog').close();el('archive-release-opinion').value='';text('archive-release-error','');el('archive-release-dialog').showModal();};el('archive-release-cancel').onclick=()=>el('archive-release-dialog').close();
  el('archive-release-form').onsubmit=async event=>{event.preventDefault();el('archive-release-save').disabled=true;try{await api('domains/restrictions','POST',{id:selectedRecord.id,opinion:el('archive-release-opinion').value});el('archive-release-dialog').close();Eam.message('专业限制已解除');load();}catch(e){text('archive-release-error',e.message);}finally{el('archive-release-save').disabled=false;}};
  el('archive-record-source').onclick=()=>Eam.go(selectedRecord.target,selectedRecord.query);
  el('archive-record-edit').onclick=()=>{const rule=selectedRecord.definition;if(!rule){Eam.message('请先绑定参数模板定义');return;}el('archive-record-dialog').close();const value=el('archive-edit-value'),upper=el('archive-edit-upper'),range=rule.type==='range';for(const input of [value,upper]){input.min=rule.min;input.max=rule.max;input.step=String(10**(-rule.precision));}value.value=range?selectedRecord.typed?.lower??'':selectedRecord.typed?.value??'';upper.value=selectedRecord.typed?.upper??'';upper.required=range;el('archive-edit-upper-field').hidden=!range;text('archive-edit-definition','固定单位 '+rule.unit+' · '+rule.min+'～'+rule.max+' · 最多'+rule.precision+'位小数 · 模板 '+rule.template+'（演示规则）');el('archive-edit-reason').value='';text('archive-edit-error','');el('archive-edit-dialog').showModal();};
  el('archive-edit-cancel').onclick=()=>el('archive-edit-dialog').close();
  el('archive-edit-form').onsubmit=async event=>{event.preventDefault();el('archive-edit-save').disabled=true;try{const rule=selectedRecord.definition,content=el('archive-edit-value').value+(rule.type==='range'?'～'+el('archive-edit-upper').value:'')+' '+rule.unit;await api('domains/parameters','PATCH',{id:selectedRecord.id,revision:selectedRecord.revision,content,reason:el('archive-edit-reason').value});el('archive-edit-dialog').close();Eam.message('参数已保存并校验');loadPanel();}catch(e){text('archive-edit-error',e.message);}finally{el('archive-edit-save').disabled=false;}};
  el('archive-repair-cancel').onclick=()=>el('archive-repair-dialog').close();el('archive-repair-form').onsubmit=async event=>{event.preventDefault();el('archive-repair-save').disabled=true;try{await api('domains/base','PATCH',{values:Object.fromEntries([...el('archive-repair-required').querySelectorAll('[data-repair-field]')].map(input=>[input.dataset.repairField,input.value])),field:selectedRecord.field,value:selectedRecord.field==='ownerId'?el('archive-repair-owner').value:el('archive-repair-value').value,revision:selectedRecord.revision,reason:el('archive-repair-reason').value});el('archive-repair-dialog').close();Eam.message('已补录，正在重新检查档案');await load();}catch(error){text('archive-repair-error',error.message);}finally{el('archive-repair-save').disabled=false;}};
  el('archive-life-open').onclick=()=>{el('archive-life-reason').value='';text('archive-life-error','');el('archive-life-dialog').showModal();};el('archive-life-cancel').onclick=()=>el('archive-life-dialog').close();
  el('archive-life-form').onsubmit=async event=>{event.preventDefault();el('archive-life-save').disabled=true;try{await api('domains/lifecycle','POST',{next:el('archive-life-next').value,reason:el('archive-life-reason').value});el('archive-life-dialog').close();Eam.message('生命周期已变更');load();}catch(e){text('archive-life-error',e.message);}finally{el('archive-life-save').disabled=false;}};
  active=new URLSearchParams(location.search).get('tab')||'overview';if(!labels[active])active='overview';await load();
})();

});
